35	Plugin? _pluginFromPackage(String name, Uri packageRoot, Set<String> appDependencies, {FileSystem? fileSystem}) {
36	  final FileSystem fs = fileSystem ?? globals.fs;
37	  final File pubspecFile = fs.file(packageRoot.resolve('pubspec.yaml'));
38	  if (!pubspecFile.existsSync()) {
39	    return null;
40	  }
41	  Object? pubspec;
42	
43	  try {
44	    pubspec = loadYaml(pubspecFile.readAsStringSync());
45	  } on YamlException catch (err) {
46	    globals.printTrace('Failed to parse plugin manifest for $name: $err');
47	    // Do nothing, potentially not a plugin.
48	  }
49	  if (pubspec == null || pubspec is! YamlMap) {
50	    return null;
51	  }
52	  final Object? flutterConfig = pubspec['flutter'];
53	  if (flutterConfig == null || flutterConfig is! YamlMap || !flutterConfig.containsKey('plugin')) {
54	    return null;
55	  }
56	  final String packageRootPath = fs.path.fromUri(packageRoot);
57	  final YamlMap? dependencies = pubspec['dependencies'] as YamlMap?;
58	  globals.printTrace('Found plugin $name at $packageRootPath');
59	  return Plugin.fromYaml(
60	    name,
61	    packageRootPath,
62	    flutterConfig['plugin'] as YamlMap?,
63	    dependencies == null ? <String>[] : <String>[...dependencies.keys.cast<String>()],
64	    fileSystem: fs,
65	    appDependencies: appDependencies,
66	  );
67	}
